const incoming = $input.first().json;
const headers = incoming.headers || {};
const body = incoming.body || incoming;

const expectedSecret = $env.TCC_UNIFAST_N8N_WEBHOOK_SECRET || '';
const providedSecret = headers['x-tcc-unifast-key'] || headers['X-TCC-UniFAST-Key'] || headers['x-tcc-unifast-webhook-secret'] || '';

if (!expectedSecret) {
  return [{
    json: {
      ok: false,
      statusCode: 500,
      error: 'TCC_UNIFAST_N8N_WEBHOOK_SECRET is not configured in n8n.',
      request_id: body.request_id || null
    }
  }];
}

if (providedSecret !== expectedSecret) {
  return [{
    json: {
      ok: false,
      statusCode: 401,
      error: 'Invalid webhook secret.',
      request_id: body.request_id || null
    }
  }];
}

if (body.event !== 'social_post_publish_requested') {
  return [{
    json: {
      ok: false,
      statusCode: 422,
      error: `Unsupported event: ${body.event || 'missing'}`,
      request_id: body.request_id || null
    }
  }];
}

const socialPost = body.social_post || {};
const batch = body.batch || null;
const message = String(socialPost.message || '').trim();

if (!message || message.length < 20) {
  return [{
    json: {
      ok: false,
      statusCode: 422,
      error: 'Facebook message is required and must be at least 20 characters.',
      request_id: body.request_id || null
    }
  }];
}

return [{
  json: {
    ok: true,
    statusCode: 200,
    event: body.event,
    request_id: body.request_id,
    requested_at: body.requested_at,
    requested_by: body.requested_by || null,
    social_post: socialPost,
    batch,
    facebook: {
      page_id: $env.FACEBOOK_PAGE_ID || '<SET_FACEBOOK_PAGE_ID>',
      message,
      publish_now: !socialPost.scheduled_for,
      scheduled_for: socialPost.scheduled_for || null,
      // Facebook scheduled posts require a Unix timestamp. This is passed only when scheduled_for exists.
      scheduled_publish_time: socialPost.scheduled_for ? Math.floor(new Date(socialPost.scheduled_for).getTime() / 1000) : null
    }
  }
}];

const item = $input.first().json;
const reviewText = [
  'TCC UniFAST Facebook post is waiting for approval.',
  '',
  `Request ID: ${item.request_id}`,
  `Title: ${item.social_post.title || '(untitled)'}`,
  `Campaign: ${item.social_post.campaign || '(none)'}`,
  `Batch: ${item.batch ? item.batch.name : '(none)'}`,
  `Schedule: ${item.social_post.scheduled_for || 'Publish immediately after approval'}`,
  '',
  'Message preview:',
  item.facebook.message
].join('\n');

return [{
  json: {
    ...item,
    approval_required: true,
    review_text: reviewText,
    manual_step: 'Review this payload, then rerun/send with social_post.approval_mode = pre_approved to publish.'
  }
}];

// This node intentionally stops auto-publishing when approval is required.
// Connect this node to Email/Slack/Discord if your n8n instance has those credentials.
const item = $input.first().json;
return [{
  json: {
    status: 'approval_required',
    request_id: item.request_id,
    review_text: item.review_text,
    manual_step: item.manual_step
  }
}];

const fb = $input.first().json;
const source = $('Validate and Normalize').first().json;
const page = $('Get Facebook Page').first().json;
const parts = String(fb.id || '').split('_');
const permalink = parts.length === 2 ? `https://www.facebook.com/${parts[0]}/posts/${parts[1]}` : null;
const scheduled = Boolean(source.social_post.scheduled_for);

return [{
  json: {
    callback_url: source.callback?.url || `${String($env.LARAVEL_API_URL || '').replace(/\/$/, '')}/api/integrations/n8n/social-media-posts/${source.social_post.id}/status`,
    callback_body: {
      request_id: source.request_id,
      status: scheduled ? 'scheduled' : 'published',
      external_post_id: fb.id || null,
      external_permalink: permalink,
      published_at: scheduled ? null : new Date().toISOString(),
      facebook_page: {
        id: page.id || null,
        name: page.name || null,
        url: page.link || null,
        picture_url: page.picture?.data?.url || null,
        cover_url: page.cover?.source || null,
        followers_count: page.followers_count ?? null,
        fan_count: page.fan_count ?? null
      },
      response: fb
    }
  }
}];
